import { mergeIntervals } from \"./intervals.mjs\";
export function clipWindow(intervals, window) {
  const clipped = intervals.map(row => ({start:Math.max(row.start,window.start),end:Math.min(row.end,window.end)}));
  return mergeIntervals(clipped.filter(row => row.start < row.end));
}
